const seen = new Set();
const rows = [];

for (const item of $input.all()) {
  const row = item.json || {};
  const group = String(row.group_name || '').trim();
  const rawUuid = String(row.pro_uuid || '').trim().toLowerCase();
  const rank = Number(row.selection_rank);

  if (!group) continue;
  if (!/^pro_[0-9a-f]{32}$/.test(rawUuid)) continue;
  if (seen.has(`${group}:${rawUuid}`)) continue;

  seen.add(`${group}:${rawUuid}`);
  rows.push({
    group_name: group,
    pro_uuid: rawUuid,
    selection_rank: Number.isFinite(rank) ? rank : 999999999,
  });
}

rows.sort((a, b) => a.group_name.localeCompare(b.group_name) || a.selection_rank - b.selection_rank || a.pro_uuid.localeCompare(b.pro_uuid));
return rows.map(row => ({ json: row }));

const historical = new Set();
for (const item of $input.all()) {
  const value = String(item.json?.pro_uuid || '').trim().toLowerCase();
  if (/^pro_[0-9a-f]{32}$/.test(value)) historical.add(value);
}

const current = $('Normalize + Deduplicate').all().map(item => item.json);
const fresh = current.filter(row => !historical.has(row.pro_uuid));

return fresh.map(row => ({
  json: {
    ...row,
    historical_duplicate: false,
  },
}));

// Keep the Snowflake identity alongside each Iterable response.
// Confirm these field names against one real Iterable response before activating.
const responses = $input.all();
const candidates = $('Exclude Historical Pro UUIDs').all();

return responses.map((item, index) => {
  const response = item.json || {};
  const source = candidates[index]?.json || {};
  const data = response.dataFields && typeof response.dataFields === 'object' ? response.dataFields : {};
  const values = [
    response.emailSendDnc,
    response.emailListUnsubscribed,
    response.emailListUnsubscribe,
    response.smsSendDnc,
    data.emailSendDnc,
    data.emailListUnsubscribed,
    data.emailListUnsubscribe,
    data.smsSendDnc,
  ];

  const normalized = values
    .filter(value => value !== undefined && value !== null)
    .map(value => typeof value === 'string' ? value.toLowerCase() === 'true' : Boolean(value));
  const hasKnownDncValue = normalized.length > 0;
  const isDnc = normalized.some(Boolean);

  return {
    json: {
      ...source,
      iterable_user_found: Object.keys(response).length > 0,
      dnc_status_known: hasKnownDncValue,
      is_dnc: isDnc,
      dnc_exclusion_reason: isDnc ? 'iterable_dnc' : (!hasKnownDncValue ? 'dnc_status_unknown' : null),
    },
  };
});

const perGroup = new Map();
const excluded = [];
const selected = [];

for (const item of $input.all()) {
  const row = item.json;
  const group = row.group_name;
  if (!perGroup.has(group)) perGroup.set(group, { candidates: 0, selected: 0, dnc: 0, unknown: 0 });
  const stats = perGroup.get(group);
  stats.candidates++;

  if (row.is_dnc === true) {
    stats.dnc++;
    excluded.push(row);
    continue;
  }
  if (row.dnc_status_known !== true) {
    stats.unknown++;
    excluded.push(row);
    continue;
  }
  if (stats.selected >= 60) continue;

  stats.selected++;
  selected.push({
    ...row,
    run_date: new Date().toISOString().slice(0, 10),
  });
}

const runDate = new Date().toISOString().slice(0, 10);
const groups = [...perGroup.entries()].map(([group_name, stats]) => ({ group_name, ...stats }));
const lines = [`Pathfinder audience run: ${runDate}`, ''];
for (const group of groups) {
  lines.push(`${group.group_name}: ${group.selected} selected | ${group.dnc} DNC | ${group.unknown} unknown/excluded`);
  for (const row of selected.filter(item => item.group_name === group.group_name)) lines.push(`- ${row.pro_uuid}`);
  lines.push('');
}
lines.push('Unknown DNC status is excluded fail-closed.');

return [{
  json: {
    run_date: runDate,
    sheet_name: `audience_${runDate}`,
    selected_rows: selected,
    excluded_rows: excluded,
    group_stats: groups,
    slack_text: lines.join('\n'),
  },
}];

const run = $('Select 60 Per Group').first().json;
return run.selected_rows.map(row => ({
  json: {
    run_date: run.run_date,
    group_name: row.group_name,
    pro_uuid: row.pro_uuid,
    selection_rank: row.selection_rank,
    dnc_status_known: row.dnc_status_known,
    is_dnc: row.is_dnc,
  },
}));
